/* Recovery check after failed Program 174. */
WITH run_context AS (SELECT run_id, run_status FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1) SELECT run_status, (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM run_context)) AS strategy_rows, (SELECT count(*) FROM msbf_ctl.run_evidence WHERE run_id=(SELECT run_id FROM run_context) AND evidence_code LIKE 'M2_6_%') AS evidence_rows, CASE WHEN run_status='M2_5_ACCEPTED' AND (SELECT count(*) FROM msbf_m2.advance_intervention_strategy_snapshot WHERE module1_run_id=(SELECT run_id FROM run_context))=0 THEN 'PASS' ELSE 'FAIL' END AS recovery_status FROM run_context;
